CREATE TABLE platform_admins (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, active boolean NOT NULL DEFAULT true);
CREATE TABLE directory_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('internal','csv','xlsx','google_sheets')), status text NOT NULL DEFAULT 'unconfigured', is_demo boolean NOT NULL, last_success_at timestamptz, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_rows (source_id uuid NOT NULL REFERENCES directory_sources(id), external_id text NOT NULL, location_id uuid NOT NULL REFERENCES provider_locations(id), source_snapshot jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), missing_from_source boolean NOT NULL DEFAULT false, PRIMARY KEY(source_id,external_id), UNIQUE(source_id,location_id));
CREATE TABLE sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES directory_sources(id), actor_id text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, rows_read integer NOT NULL DEFAULT 0, inserted integer NOT NULL DEFAULT 0, updated integer NOT NULL DEFAULT 0, unchanged integer NOT NULL DEFAULT 0, rejected integer NOT NULL DEFAULT 0, status text NOT NULL, error_summary text);
CREATE TABLE provider_field_locks (location_id uuid NOT NULL REFERENCES provider_locations(id), field_name text NOT NULL, reason text NOT NULL, locked_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(location_id,field_name));
